import{f as t,D as i,c as d,o as s,k as n,H as l,aq as o,a}from"./chunks/framework.D9EfIZ-r.js";const k=JSON.parse('{"title":"Gendergerechte Sprache in der Anwendung","description":"","frontmatter":{},"headers":[],"relativePath":"technik/adr/adr-gender-sensitive-language.md","filePath":"technik/adr/adr-gender-sensitive-language.md"}'),u={name:"technik/adr/adr-gender-sensitive-language.md"};function h(c,e,g,p,m,f){const r=i("adr-status");return s(),d("div",null,[e[0]||(e[0]=n("h1",{id:"gendergerechte-sprache-in-der-anwendung",tabindex:"-1"},[a("Gendergerechte Sprache in der Anwendung "),n("a",{class:"header-anchor",href:"#gendergerechte-sprache-in-der-anwendung","aria-label":'Permalink to "Gendergerechte Sprache in der Anwendung"'},"​")],-1)),e[1]||(e[1]=n("h2",{id:"status",tabindex:"-1"},[a("Status "),n("a",{class:"header-anchor",href:"#status","aria-label":'Permalink to "Status"'},"​")],-1)),l(r,{status:"accepted"}),e[2]||(e[2]=o('<h2 id="kontext" tabindex="-1">Kontext <a class="header-anchor" href="#kontext" aria-label="Permalink to &quot;Kontext&quot;">​</a></h2><p>Die Verwendung gendergerechter Sprache im Wahllokalsystem ist ein wichtiger Aspekt, um Inklusivität und Gleichberechtigung zu fördern. Die Nutzer*innen kommen aus unterschiedlichen Hintergründen und es ist uns wichtig, alle Geschlechter gerecht zu adressieren, damit sich alle Benutzergruppen gleichermaßen angesprochen und wertgeschätzt fühlen.</p><h2 id="entscheidung" tabindex="-1">Entscheidung <a class="header-anchor" href="#entscheidung" aria-label="Permalink to &quot;Entscheidung&quot;">​</a></h2><p>Den städtischen Vorgaben folgend, soll vorrangig der Genderstern verwendet werden, ergänzt durch geschlechtsneutrale Formulierungen. Folgende Ausnahmen wurden hierbei vom Fachbereich definiert:</p><ul><li>Im Navigationsmenü der Anwendung soll <code>Kandidatinnen- und Kandidatenstimmen</code> ausgeschrieben werden</li><li><code>Wähler*innen</code> kann, wo sinnvoll und fachlich korrekt, durch <code>Wahlberechtigte</code> ersetzt werden</li></ul><p>Weiterhin wurden die folgenden Bezeichnungen festgelegt:</p><ul><li><code>Bewerber*innen</code> ❌ → <code>Kandidat*innen</code> ✅</li></ul><h2 id="konsequenzen" tabindex="-1">Konsequenzen <a class="header-anchor" href="#konsequenzen" aria-label="Permalink to &quot;Konsequenzen&quot;">​</a></h2><h3 id="positiv" tabindex="-1">positiv <a class="header-anchor" href="#positiv" aria-label="Permalink to &quot;positiv&quot;">​</a></h3><ul><li>Förderung von Inklusivität und Gleichberechtigung.</li><li>Verbesserung der Nutzererfahrung und Zufriedenheit bei einer vielfältigen Benutzerbasis.</li></ul><h3 id="negativ" tabindex="-1">negativ <a class="header-anchor" href="#negativ" aria-label="Permalink to &quot;negativ&quot;">​</a></h3><ul><li>Erhöhter Aufwand bei der Anpassung von bestehenden Texten in der Anwendung und Dokumentation und der kontinuierlichen Pflege von neuen Inhalten.</li></ul>',12))])}const v=t(u,[["render",h]]);export{k as __pageData,v as default};
